	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_ENUMERATIONs_reference, &stage.ATTRIBUTE_DEFINITION_ENUMERATIONs_instance, &stage.ATTRIBUTE_DEFINITION_ENUMERATIONs_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_ENUMERATION_Renderings_reference, &stage.ATTRIBUTE_DEFINITION_ENUMERATION_Renderings_instance, &stage.ATTRIBUTE_DEFINITION_ENUMERATION_Renderings_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_INTEGERs_reference, &stage.ATTRIBUTE_DEFINITION_INTEGERs_instance, &stage.ATTRIBUTE_DEFINITION_INTEGERs_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_INTEGER_Renderings_reference, &stage.ATTRIBUTE_DEFINITION_INTEGER_Renderings_instance, &stage.ATTRIBUTE_DEFINITION_INTEGER_Renderings_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_REALs_reference, &stage.ATTRIBUTE_DEFINITION_REALs_instance, &stage.ATTRIBUTE_DEFINITION_REALs_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_REAL_Renderings_reference, &stage.ATTRIBUTE_DEFINITION_REAL_Renderings_instance, &stage.ATTRIBUTE_DEFINITION_REAL_Renderings_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_Renderings_reference, &stage.ATTRIBUTE_DEFINITION_Renderings_instance, &stage.ATTRIBUTE_DEFINITION_Renderings_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_STRINGs_reference, &stage.ATTRIBUTE_DEFINITION_STRINGs_instance, &stage.ATTRIBUTE_DEFINITION_STRINGs_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_STRING_Renderings_reference, &stage.ATTRIBUTE_DEFINITION_STRING_Renderings_instance, &stage.ATTRIBUTE_DEFINITION_STRING_Renderings_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_XHTMLs_reference, &stage.ATTRIBUTE_DEFINITION_XHTMLs_instance, &stage.ATTRIBUTE_DEFINITION_XHTMLs_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_DEFINITION_XHTML_Renderings_reference, &stage.ATTRIBUTE_DEFINITION_XHTML_Renderings_instance, &stage.ATTRIBUTE_DEFINITION_XHTML_Renderings_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_VALUE_BOOLEANs_reference, &stage.ATTRIBUTE_VALUE_BOOLEANs_instance, &stage.ATTRIBUTE_VALUE_BOOLEANs_referenceOrder)

	__gong__clearReferences(&stage.ATTRIBUTE_VALUE_DATEs_reference, &stage.ATTRIBUTE_VALUE_DATEs_instance, &stage.ATTRIBUTE_VALUE_DATEs_referenceOrder)

